// b00o2 is the order-2 part of block hhhh,hhhh, <i,j,k,l|M|m,n,o,i1>.
func (el *Elem) b00o2(i, j, k, l, m, n, o, i1 int) float64 {
	var v float64
	// (1)
	v += el.b00o2g0(i, j, k, l, m, n, o, i1)
	return v
}

// B00 is block hhhh,hhhh of the secular matrix,
// <i,j,k,l|M|m,n,o,i1>, summed over the orders the scheme keeps.
func (el *Elem) B00(i, j, k, l, m, n, o, i1 int) float64 {
	var v float64
	if el.maxOrder[0] >= 0 {
		v += el.b00o0(i, j, k, l, m, n, o, i1)
	}
	if el.maxOrder[0] >= 1 {
		v += el.b00o1(i, j, k, l, m, n, o, i1)
	}
	if el.maxOrder[0] >= 2 {
		v += el.b00o2(i, j, k, l, m, n, o, i1)
	}
	return v
}
